create extension if not exists pgcrypto;
drop table if exists public.order_items,public.payments,public.orders,public.inventory,public.products,public.categories,public.coupons,public.offers,public.delivery_rates,public.delivery_zones,public.delivery_workers,public.addresses,public.store_settings,public.profiles cascade;
create table profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,phone text,role text not null default 'customer' check(role in('customer','staff','admin','delivery_worker')),created_at timestamptz default now(),updated_at timestamptz default now());
create table categories(id uuid primary key default gen_random_uuid(),name text not null,slug text unique not null,description text,image_url text,active boolean default true,created_at timestamptz default now());
create table products(id uuid primary key default gen_random_uuid(),category_id uuid references categories(id) on delete set null,name text not null,slug text unique not null,description text,unit text,price numeric(12,2) not null,sale_price numeric(12,2),image_url text,active boolean default true,featured boolean default false,created_at timestamptz default now(),updated_at timestamptz default now());
create table inventory(product_id uuid primary key references products(id) on delete cascade,stock int not null default 0,low_stock int not null default 5,updated_at timestamptz default now());
create table addresses(id uuid primary key default gen_random_uuid(),customer_id uuid references profiles(id) on delete cascade,label text default 'Home',full_name text,phone text,address_line1 text,address_line2 text,city text,state text,pincode text,latitude numeric,longitude numeric,is_default boolean default false,created_at timestamptz default now());
create table delivery_workers(id uuid primary key references profiles(id) on delete cascade,name text,phone text,active boolean default true,vehicle text,created_at timestamptz default now());
create table delivery_zones(id uuid primary key default gen_random_uuid(),name text not null,min_km numeric default 0,max_km numeric not null,active boolean default true);
create table delivery_rates(id uuid primary key default gen_random_uuid(),zone_id uuid references delivery_zones(id) on delete cascade,rate numeric(12,2) default 0,free_above numeric(12,2),active boolean default true);
create table coupons(id uuid primary key default gen_random_uuid(),code text unique not null,discount_type text,discount_value numeric(12,2) default 0,min_order numeric(12,2) default 0,max_discount numeric(12,2),usage_limit int,used_count int default 0,starts_at timestamptz,ends_at timestamptz,active boolean default true);
create table offers(id uuid primary key default gen_random_uuid(),name text not null,type text,value numeric(12,2) default 0,min_order numeric(12,2) default 0,active boolean default true,starts_at timestamptz,ends_at timestamptz,category_id uuid references categories(id),product_id uuid references products(id));
create table orders(id uuid primary key default gen_random_uuid(),order_number text unique not null,customer_id uuid references profiles(id) on delete set null,status text not null default 'NEW',subtotal numeric(12,2) not null,discount numeric(12,2) default 0,delivery_fee numeric(12,2) default 0,total numeric(12,2) not null,customer_name text,customer_phone text,delivery_address text,pincode text,coupon_code text,delivery_worker_id uuid references delivery_workers(id),payment_status text default 'PENDING',created_at timestamptz default now(),updated_at timestamptz default now());
create table order_items(id uuid primary key default gen_random_uuid(),order_id uuid references orders(id) on delete cascade,product_id uuid references products(id) on delete set null,product_name text not null,quantity int not null,unit_price numeric(12,2) not null,line_total numeric(12,2) not null);
create table payments(id uuid primary key default gen_random_uuid(),order_id uuid references orders(id) on delete cascade,provider text default 'razorpay',provider_order_id text,provider_payment_id text,amount numeric(12,2),status text,created_at timestamptz default now());
create table store_settings(key text primary key,value text not null);
insert into store_settings values('name','SHOP'),('phone',''),('whatsapp',''),('free_delivery','750'),('max_delivery_km','10'),('closed','false');
create or replace function handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$begin insert into profiles(id,full_name) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',''));return new;end$$;
create trigger on_auth_user_created after insert on auth.users for each row execute function handle_new_user();
create or replace function current_role() returns text language sql stable security definer set search_path=public as $$select role from profiles where id=auth.uid()$$;
create or replace function is_staff() returns boolean language sql stable security definer set search_path=public as $$select current_role() in('admin','staff')$$;
create or replace function is_admin() returns boolean language sql stable security definer set search_path=public as $$select current_role()='admin'$$;
create or replace function create_order(p_items jsonb,p_name text,p_phone text,p_address text,p_pincode text,p_coupon text default null) returns uuid language plpgsql security definer set search_path=public as $$declare uid uuid:=auth.uid();i jsonb;p uuid;q int;pr products%rowtype;s numeric:=0;o uuid;n text;begin if uid is null then raise exception 'Login required';end if;for i in select * from jsonb_array_elements(p_items) loop p:=(i->>'product_id')::uuid;q:=(i->>'quantity')::int;select * into pr from products where id=p and active;if pr.id is null then raise exception 'Product unavailable';end if;if exists(select 1 from inventory where product_id=p and stock<q) then raise exception 'Insufficient stock';end if;s:=s+coalesce(pr.sale_price,pr.price)*q;end loop;n:='SHP-'||to_char(now(),'YYYYMMDDHH24MISS')||'-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,4));insert into orders(order_number,customer_id,subtotal,total,customer_name,customer_phone,delivery_address,pincode,coupon_code)values(n,uid,s,s,p_name,p_phone,p_address,p_pincode,p_coupon)returning id into o;for i in select * from jsonb_array_elements(p_items) loop p:=(i->>'product_id')::uuid;q:=(i->>'quantity')::int;select * into pr from products where id=p;insert into order_items(order_id,product_id,product_name,quantity,unit_price,line_total)values(o,p,pr.name,q,coalesce(pr.sale_price,pr.price),coalesce(pr.sale_price,pr.price)*q);update inventory set stock=stock-q where product_id=p;end loop;return o;end$$;
alter table profiles enable row level security;alter table categories enable row level security;alter table products enable row level security;alter table inventory enable row level security;alter table addresses enable row level security;alter table orders enable row level security;alter table order_items enable row level security;alter table payments enable row level security;alter table coupons enable row level security;alter table offers enable row level security;alter table delivery_workers enable row level security;alter table delivery_zones enable row level security;alter table delivery_rates enable row level security;alter table store_settings enable row level security;
create policy categories_public on categories for select using(active or is_staff());create policy products_public on products for select using(active or is_staff());create policy settings_public on store_settings for select using(true);create policy profile_self on profiles for select using(id=auth.uid() or is_staff());create policy profile_update on profiles for update using(id=auth.uid() or is_admin()) with check(id=auth.uid() or is_admin());create policy products_staff on products for all using(is_staff()) with check(is_staff());create policy categories_staff on categories for all using(is_staff()) with check(is_staff());create policy inventory_staff on inventory for all using(is_staff()) with check(is_staff());create policy addresses_self on addresses for all using(customer_id=auth.uid() or is_staff()) with check(customer_id=auth.uid() or is_staff());create policy orders_customer on orders for select using(customer_id=auth.uid() or is_staff() or delivery_worker_id=auth.uid());create policy orders_staff on orders for all using(is_staff()) with check(is_staff());create policy order_items_customer on order_items for select using(exists(select 1 from orders where orders.id=order_id and (orders.customer_id=auth.uid() or is_staff())));create policy order_items_staff on order_items for all using(is_staff()) with check(is_staff());create policy payments_staff on payments for all using(is_staff()) with check(is_staff());create policy coupons_staff on coupons for all using(is_staff()) with check(is_staff());create policy offers_staff on offers for all using(is_staff()) with check(is_staff());create policy delivery_staff on delivery_workers for all using(is_staff()) with check(is_staff());create policy zones_staff on delivery_zones for all using(is_staff()) with check(is_staff());create policy rates_staff on delivery_rates for all using(is_staff()) with check(is_staff());
-- After signup: update public.profiles set role='admin' where id=(select id from auth.users where email='YOUR_EMAIL');
